#include "network.h"
#include "protocol.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int read_key(const char*path,char*out,size_t size){FILE*f=fopen(path,"r");size_t n;if(!f||!fgets(out,(int)size,f)){if(f)fclose(f);return-1;}fclose(f);n=strlen(out);while(n&&(out[n-1]=='\n'||out[n-1]=='\r'||out[n-1]==' '))out[--n]=0;return n?0:-1;}
static void usage(void){fputs("usage: councilctl --host H --port P --name N --key-file F (say TEXT|status|grant NAME|end-propose REASON|end-vote 'close REASON'|end-vote 'continue WHAT_REMAINS')\n",stderr);}
int main(int argc,char**argv){contact hub;const char*name=NULL,*key_file=NULL,*command=NULL,*argument="";network_socket socket;char line[COUNCIL_MESSAGE_LENGTH];int i,result=0;memset(&hub,0,sizeof(hub));for(i=1;i<argc;i++){if(!strcmp(argv[i],"--host")&&++i<argc)snprintf(hub.host,sizeof(hub.host),"%s",argv[i]);else if(!strcmp(argv[i],"--port")&&++i<argc)hub.port=(uint16_t)atoi(argv[i]);else if(!strcmp(argv[i],"--name")&&++i<argc)name=argv[i];else if(!strcmp(argv[i],"--key-file")&&++i<argc)key_file=argv[i];else if(!command){command=argv[i];if(i+1<argc)argument=argv[++i];}else{usage();return 2;}}if(!hub.host[0]||!hub.port||!name||!key_file||!command||read_key(key_file,hub.shared_key,sizeof(hub.shared_key))){usage();return 2;}if(strchr(argument,'\n')||strchr(argument,'\r'))return 2;if(network_start()||protocol_connect_identity(&hub,name,&socket)){fputs("connection or authentication failed\n",stderr);return 1;}if(!strcmp(command,"say"))snprintf(line,sizeof(line),"SAY %s\n",argument);else if(!strcmp(command,"status"))snprintf(line,sizeof(line),"STATUS\n");else if(!strcmp(command,"grant"))snprintf(line,sizeof(line),"GRANT %s\n",argument);else if(!strcmp(command,"end-propose"))snprintf(line,sizeof(line),"END_PROPOSE %s\n",argument);else if(!strcmp(command,"end-vote"))snprintf(line,sizeof(line),"END_VOTE %s\n",argument);else{usage();network_close(socket);return 2;}if(network_send(socket,line)){network_close(socket);return 1;}while(network_read_line(socket,line,sizeof(line))>=0){puts(line);if(!strncmp(line,"ERROR",5))result=1;if(strcmp(command,"status")||!strcmp(line,"END"))break;}network_close(socket);network_stop();return result;}
